export function is_palindrome(s: string): boolean {
  const chars: string[] = Array.from(s);
  let i = 0;
  let j = chars.length - 1;
  while (i < j) {
    if (chars[i] !== chars[j]) {
      return false;
    }
    i++;
    j--;
  }
  return true;
}

