export function digit_sum(n: number): number {
  if (!Number.isFinite(n) || n < 0) {
    throw new RangeError("digit_sum requires a finite number n >= 0");
  }

  if (Number.isInteger(n)) {
    // BigInt gives the exact decimal expansion, even beyond 2^53.
    let v = BigInt(n);
    let sum = 0;
    while (v > 0n) {
      sum += Number(v % 10n);
      v /= 10n;
    }
    return sum;
  }

  // Fallback for non-integers: sum the digit characters of the
  // mantissa portion of the string representation.
  const s = n.toString();
  const mantissa = s.split("e")[0];
  let sum = 0;
  for (const ch of mantissa) {
    if (ch >= "0" && ch <= "9") {
      sum += ch.charCodeAt(0) - 48;
    }
  }
  return sum;
}

