export function pairs_summing(xs: number[], target: number): number {
  const sorted = [...xs].sort((a, b) => a - b);
  let lastAtMost = sorted.length - 1;
  let lastBelow = sorted.length - 1;
  let count = 0;

  // As the left value increases, both right-hand boundaries move only left.
  for (let i = 0; i < sorted.length - 1; i++) {
    const left = sorted[i];

    while (lastAtMost > i && left + sorted[lastAtMost] > target) {
      lastAtMost--;
    }
    while (lastBelow > i && left + sorted[lastBelow] >= target) {
      lastBelow--;
    }

    count += Math.max(i, lastAtMost) - Math.max(i, lastBelow);
  }

  return count;
}

