  if (s.length === 0) {
    return null;
  }

  const words = s.split(" ").filter((w) => w.length > 0);
  if (words.length === 0) {
    return null;
  }

  // Map preserves insertion order, i.e. order of first appearance.
  const counts = new Map<string, number>();
  for (const w of words) {
    counts.set(w, (counts.get(w) ?? 0) + 1);
  }

  let best: string | null = null;
  let bestCount = 0;
  for (const [word, count] of counts) {
    if (count > bestCount) {
      best = word;
      bestCount = count;
    }
  }

  return best;
}

