function area(shape: Shape): number {
  switch (shape.kind) {
    case "Circle":
      return 3.14159 * shape.radius * shape.radius;
    case "Rect":
      return shape.width * shape.height;
    case "Triangle":
      return (shape.base * shape.height) / 2.0;
    default: {
      const _exhaustive: never = shape;
      return _exhaustive;
    }
  }
}

