type Result<T> = { ok: true; value: T } | { ok: false; error: string };

const INTEGER_RE = /^-?[0-9]+$/;

function parseItem(item: string): [string, number] | null {
  const parts = item.split("=");
  if (parts.length !== 2) {
    return null;
  }
  const key = parts[0];
  const valueText = parts[1];
  if (!INTEGER_RE.test(valueText)) {
    return null;
  }
  let value = Number(valueText);
  if (!Number.isFinite(value)) {
    return null;
  }
  if (Object.is(value, -0)) {
    value = 0;
  }
  return [key, value];
}

export function parse_pairs(s: string): Result<([string, number])[]> {
  if (s === "") {
    return { ok: true, value: [] };
  }
  const items = s.split(";");
  const out: [string, number][] = [];
  for (const item of items) {
    const pair = parseItem(item);
    if (pair === null) {
      return { ok: false, error: "bad item: " + item };
    }
    out.push(pair);
  }
  return { ok: true, value: out };
}

