export function parse_pairs(s: string): Result<([string, number])[]> {
  const pairs: [string, number][] = [];
  if (s === "") return { ok: true, value: pairs };

  for (const item of s.split(";")) {
    const separator = item.indexOf("=");
    if (separator === -1 || separator !== item.lastIndexOf("=")) {
      return { ok: false, error: "bad item: " + item };
    }

    const text = item.slice(separator + 1);
    if (!/^-?[0-9]+$/.test(text)) {
      return { ok: false, error: "bad item: " + item };
    }

    const value = Number(text);
    if (!Number.isInteger(value)) {
      return { ok: false, error: "bad item: " + item };
    }

    pairs.push([item.slice(0, separator), value]);
  }

  return { ok: true, value: pairs };
}

