type Result<T> = { ok: true; value: T } | { ok: false; error: string };

const INTEGER_PATTERN = /^-?[0-9]+$/;

function normalize(n: number): number {
  // Convert -0 to 0
  return n === 0 ? 0 : n;
}

export function rpn(tokens: string[]): Result<number> {
  const stack: number[] = [];

  for (const token of tokens) {
    if (token === "+" || token === "-" || token === "*" || token === "/") {
      if (stack.length < 2) {
        return { ok: false, error: "stack underflow" };
      }
      const b = stack.pop() as number;
      const a = stack.pop() as number;
      let result: number;
      switch (token) {
        case "+":
          result = a + b;
          break;
        case "-":
          result = a - b;
          break;
        case "*":
          result = a * b;
          break;
        case "/":
          if (b === 0) {
            return { ok: false, error: "division by zero" };
          }
          result = Math.trunc(a / b);
          break;
      }
      stack.push(normalize(result));
    } else if (INTEGER_PATTERN.test(token)) {
      stack.push(normalize(Number(token)));
    } else {
      return { ok: false, error: "bad token: " + token };
    }
  }

  if (stack.length !== 1) {
    return { ok: false, error: "expected one value" };
  }
  return { ok: true, value: stack[0] as number };
}

