type Student = { name: string; scores: number[] };

function averageScore(scores: number[]): number {
  if (scores.length === 0) return 0;
  let sum = 0;
  for (const s of scores) sum += s;
  return Math.trunc(sum / scores.length);
}

function letterGrade(avg: number): string {
  if (avg >= 90) return "A";
  if (avg >= 80) return "B";
  if (avg >= 70) return "C";
  if (avg >= 60) return "D";
  return "F";
}

export function report_card(students: Student[]): ([string, string])[] {
  const result: ([string, string])[] = [];
  for (const student of students) {
    const avg = averageScore(student.scores);
    result.push([student.name, letterGrade(avg)]);
  }
  return result;
}

