export function report_card(students: Student[]): ([string, string])[] {
  return students.map(({ name, scores }): [string, string] => {
    const sum = scores.reduce((total, score) => total + score, 0);
    const average = scores.length === 0 ? 0 : Math.trunc(sum / scores.length);

    let grade = "F";
    if (average >= 90) grade = "A";
    else if (average >= 80) grade = "B";
    else if (average >= 70) grade = "C";
    else if (average >= 60) grade = "D";

    return [name, grade];
  });
}

